reference_solution:
def shortest_word_distance(words, word1, word2):
    latest_first = latest_second = -1
    best = len(words)
    for index, word in enumerate(words):
        if word == word1:
            latest_first = index
        elif word == word2:
            latest_second = index
        if latest_first >= 0 and latest_second >= 0:
            best = min(best, abs(latest_first - latest_second))
    return best

